CREATE TABLE atlys_dataset.traveller_removed (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, minute-resolution' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios, android, web-user-b2c, desktop (4 values)', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; 4.3% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version (3 values)', `geoip_country_code` LowCardinality(String) COMMENT 'geo country from ip (7 values)', `city` LowCardinality(String) COMMENT 'geo city from ip (7 values)', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id who owns the group' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'application id, joins base funnel tables' CODEC(ZSTD(1)), `group_id` FixedString(32) COMMENT 'group id, joins all group funnel stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination iso-2 (14 values)', `group_size` UInt8 COMMENT 'travellers planned in group, range 2-6' CODEC(T64, ZSTD(1)), `traveller_index` UInt8 COMMENT 'co-traveller slot removed, range 0-5' CODEC(T64, ZSTD(1)), INDEX idx_application_id application_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (group_size, group_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'traveller_removed: a co-traveller is dropped, pairs with traveller_added for churn rate (spec: group applications)'
CREATE TABLE atlys_dataset.group_submitted (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, minute-resolution' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios, android, web-user-b2c, desktop (4 values)', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; 6.5% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version (3 values)', `geoip_country_code` LowCardinality(String) COMMENT 'geo country from ip (7 values)', `city` LowCardinality(String) COMMENT 'geo city from ip (7 values)', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id who owns the group' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'application id, joins base funnel tables' CODEC(ZSTD(1)), `group_id` FixedString(32) COMMENT 'group id, joins all group funnel stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination iso-2 (14 values)', `group_size` UInt8 COMMENT 'travellers planned in group, range 2-6' CODEC(T64, ZSTD(1)), `travellers_submitted` UInt8 COMMENT 'travellers included at submit, range 1-6' CODEC(T64, ZSTD(1)), INDEX idx_application_id application_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (group_size, destination, device_type, group_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'group_submitted: the group is submitted, funnel completion stage joined to group_started via group_id (spec: group applications)'
CREATE TABLE atlys_dataset.group_started (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, minute-resolution' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios, android, web-user-b2c, desktop (4 values)', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; 6.3% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version (3 values)', `geoip_country_code` LowCardinality(String) COMMENT 'geo country from ip (7 values)', `city` LowCardinality(String) COMMENT 'geo city from ip (7 values)', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id who starts the group' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'application id, joins base funnel tables' CODEC(ZSTD(1)), `group_id` FixedString(32) COMMENT 'group id, joins all group funnel stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination iso-2 (14 values)', `group_size` UInt8 COMMENT 'travellers planned in group, range 2-6' CODEC(T64, ZSTD(1)), INDEX idx_application_id application_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (group_size, destination, device_type, group_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'group_started: group flow begins, funnel stage 1 of group applications (spec: group applications)'
CREATE TABLE atlys_dataset.traveller_added (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, minute-resolution' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios, android, web-user-b2c, desktop (4 values)', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; 6.3% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version (3 values)', `geoip_country_code` LowCardinality(String) COMMENT 'geo country from ip (7 values)', `city` LowCardinality(String) COMMENT 'geo city from ip (7 values)', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id who owns the group' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'application id, joins base funnel tables' CODEC(ZSTD(1)), `group_id` FixedString(32) COMMENT 'group id, joins all group funnel stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination iso-2 (14 values)', `group_size` UInt8 COMMENT 'travellers planned in group, range 2-6' CODEC(T64, ZSTD(1)), `traveller_index` UInt8 COMMENT 'co-traveller slot added, range 0-5' CODEC(T64, ZSTD(1)), `relation` LowCardinality(String) COMMENT 'relation to primary traveller (5 values)', `docs_complete` UInt8 COMMENT 'flag: 1 if docs complete at add-time' CODEC(T64, ZSTD(1)), INDEX idx_application_id application_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (group_size, docs_complete, group_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'traveller_added: a co-traveller is added, tracks churn and docs completion by group size (spec: group applications)'